package com.xpertsedge.lms.teaching;

import com.xpertsedge.lms.auth.IdentityService;
import com.xpertsedge.lms.common.ApiException;
import com.xpertsedge.lms.domain.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.time.*;
import java.sql.Timestamp;
import java.net.URI;
import java.nio.charset.StandardCharsets;

@RestController @RequestMapping("/api/workspace")
public class TeachingController {
    private final JdbcTemplate db;
    private final IdentityService identities;
    private final CourseRepository courses;
    private final EnrolmentRepository enrolments;
    private final UserRepository users;
    private final Clock clock;
    private final com.xpertsedge.lms.notifications.LearningEmails emails;
    public TeachingController(JdbcTemplate db,IdentityService identities,CourseRepository courses,EnrolmentRepository enrolments,UserRepository users,Clock clock,com.xpertsedge.lms.notifications.LearningEmails emails){this.emails=emails;this.db=db;this.identities=identities;this.courses=courses;this.enrolments=enrolments;this.users=users;this.clock=clock;}
    private ApiException bad(String message){return new ApiException(HttpStatus.BAD_REQUEST,message);}
    private void require(boolean condition){if(!condition)throw new ApiException(HttpStatus.FORBIDDEN,"You do not have access to this record.");}
    private UUID uuid(Object value){return UUID.fromString(value.toString());}
    private Map<String,Object> one(String sql,Object... args){return db.query(sql,(rs,n)->{Map<String,Object> row=new LinkedHashMap<>();var meta=rs.getMetaData();for(int i=1;i<=meta.getColumnCount();i++)row.put(meta.getColumnLabel(i),rs.getObject(i));return row;},args).stream().findFirst().orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Record not found."));}
    private boolean active(AppUser user,String course){return user.isEnabled()&&courses.findById(course).map(Course::isPublished).orElse(false)&&enrolments.findByStudentIdAndCourseId(user.getId(),course).map(e->e.activeOn(LocalDate.now(clock.withZone(ZoneId.of("Asia/Kolkata"))))).orElse(false);}
    private boolean canRead(AppUser u,String course){return courses.findById(course).map(c->switch(u.getRole()){case ADMIN->true;case TRAINER->u.getId().equals(c.getTrainerId());case STUDENT->active(u,course);}).orElse(false);}
    private void teach(AppUser u,String course){require(u.getRole()!=Role.STUDENT&&canRead(u,course));}
    private boolean member(UUID batch,UUID student){return db.queryForObject("SELECT COUNT(*) FROM batch_members WHERE batch_id=? AND student_id=?",Integer.class,batch,student)>0;}
    private boolean sessionVisible(Map<String,Object> row,AppUser u){return canRead(u,row.get("course_id").toString())&&(u.getRole()!=Role.STUDENT||row.get("batch_id")==null||member(uuid(row.get("batch_id")),u.getId()));}
    private boolean learnerInSession(Map<String,Object> row,UUID student){AppUser u=users.findById(student).orElseThrow(()->bad("Student not found."));return u.getRole()==Role.STUDENT&&active(u,row.get("course_id").toString())&&(row.get("batch_id")==null||member(uuid(row.get("batch_id")),student));}
    private List<Map<String,Object>> visible(String table,AppUser u){return db.queryForList("SELECT * FROM "+table).stream().filter(r->canRead(u,r.get("course_id").toString())).toList();}

    @GetMapping("/courses") public List<?> myCourses(Authentication auth){AppUser u=identities.current(auth);return courses.findAll().stream().filter(c->canRead(u,c.getId())).map(c->Map.of("id",c.getId(),"name",c.getName(),"category",c.getCategory(),"description",c.getDescription())).toList();}
    @GetMapping("/learners") public List<?> learners(Authentication auth){AppUser u=identities.current(auth);require(u.getRole()!=Role.STUDENT);return enrolments.findAll().stream().filter(e->canRead(u,e.getCourseId())).map(e->{AppUser student=users.findById(e.getStudentId()).orElseThrow();return Map.of("studentId",student.getId(),"name",student.getName(),"email",student.getEmail(),"courseId",e.getCourseId(),"active",active(student,e.getCourseId()));}).toList();}
    public record BatchInput(@NotBlank @Size(max=60)String courseId,@NotBlank @Size(max=150)String name,@NotBlank @Size(max=300)String schedule,@NotNull LocalDate startsOn,@NotNull LocalDate endsOn){}
    @GetMapping("/batches") public List<?> batches(Authentication auth){AppUser u=identities.current(auth);return visible("teaching_batches",u).stream().filter(r->u.getRole()!=Role.STUDENT||member(uuid(r.get("id")),u.getId())).map(r->{Map<String,Object> copy=new LinkedHashMap<>(r);if(u.getRole()!=Role.STUDENT)copy.put("members",db.queryForList("SELECT student_id FROM batch_members WHERE batch_id=?",r.get("id")));return copy;}).toList();}
    @PostMapping("/batches") @Transactional public Map<String,Object> createBatch(@Valid @RequestBody BatchInput r,Authentication a){return saveBatch(UUID.randomUUID(),r,identities.current(a),false);}
    @PutMapping("/batches/{id}") @Transactional public Map<String,Object> updateBatch(@PathVariable UUID id,@Valid @RequestBody BatchInput r,Authentication a){return saveBatch(id,r,identities.current(a),true);}
    private Map<String,Object> saveBatch(UUID id,BatchInput r,AppUser u,boolean update){teach(u,r.courseId());if(r.endsOn().isBefore(r.startsOn()))throw bad("End date must follow start date.");if(update){Map<String,Object> old=one("SELECT * FROM teaching_batches WHERE id=?",id);teach(u,old.get("course_id").toString());if(!old.get("course_id").equals(r.courseId()))throw bad("A batch course cannot be changed.");db.update("UPDATE teaching_batches SET name=?,schedule=?,starts_on=?,ends_on=? WHERE id=?",r.name().strip(),r.schedule().strip(),r.startsOn(),r.endsOn(),id);}else db.update("INSERT INTO teaching_batches(id,course_id,name,schedule,starts_on,ends_on) VALUES(?,?,?,?,?,?)",id,r.courseId(),r.name().strip(),r.schedule().strip(),r.startsOn(),r.endsOn());return Map.of("id",id);}
    public record MembersInput(@NotNull @Size(max=1000)List<@NotNull UUID> studentIds){}
    @PutMapping("/batches/{id}/members") @Transactional public Map<String,Object> members(@PathVariable UUID id,@Valid @RequestBody MembersInput r,Authentication a){AppUser u=identities.current(a);String course=one("SELECT * FROM teaching_batches WHERE id=?",id).get("course_id").toString();teach(u,course);for(UUID student:r.studentIds()){AppUser s=users.findById(student).orElseThrow(()->bad("Student not found."));if(s.getRole()!=Role.STUDENT||!active(s,course))throw bad("Batch members must have active course enrolment.");}db.update("DELETE FROM batch_members WHERE batch_id=?",id);for(UUID student:new HashSet<>(r.studentIds()))db.update("INSERT INTO batch_members(batch_id,student_id) VALUES(?,?)",id,student);return Map.of("saved",true);}

    public record SessionInput(@NotBlank @Size(max=60)String courseId,UUID batchId,@NotBlank @Size(max=150)String title,@NotNull OffsetDateTime startsAt,@Min(5) @Max(480)int durationMinutes,@NotBlank @Size(max=2000)String meetingUrl,@Pattern(regexp="SCHEDULED|COMPLETED|CANCELLED") @NotNull String status){}
    @GetMapping("/sessions") public List<?> sessions(Authentication a){AppUser u=identities.current(a);return visible("live_sessions",u).stream().filter(r->sessionVisible(r,u)).toList();}
    @PostMapping("/sessions") @Transactional public Map<String,Object> createSession(@Valid @RequestBody SessionInput r,Authentication a){return saveSession(UUID.randomUUID(),r,identities.current(a),false);}
    @PutMapping("/sessions/{id}") @Transactional public Map<String,Object> updateSession(@PathVariable UUID id,@Valid @RequestBody SessionInput r,Authentication a){return saveSession(id,r,identities.current(a),true);}
    private Map<String,Object> saveSession(UUID id,SessionInput r,AppUser u,boolean update){teach(u,r.courseId());try{URI uri=URI.create(r.meetingUrl());if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw bad("Use an HTTPS meeting URL.");}catch(IllegalArgumentException ex){throw bad("Use an HTTPS meeting URL.");}if(r.batchId()!=null&&!one("SELECT * FROM teaching_batches WHERE id=?",r.batchId()).get("course_id").equals(r.courseId()))throw bad("Batch must belong to the course.");if(update){var old=one("SELECT * FROM live_sessions WHERE id=?",id);teach(u,old.get("course_id").toString());if(!old.get("course_id").equals(r.courseId())||!Objects.equals(old.get("batch_id"),r.batchId()))throw bad("Session course and batch cannot be changed.");db.update("UPDATE live_sessions SET title=?,starts_at=?,duration_minutes=?,meeting_url=?,status=? WHERE id=?",r.title().strip(),r.startsAt(),r.durationMinutes(),r.meetingUrl(),r.status(),id);}else db.update("INSERT INTO live_sessions(id,course_id,batch_id,title,starts_at,duration_minutes,meeting_url,status) VALUES(?,?,?,?,?,?,?,?)",id,r.courseId(),r.batchId(),r.title().strip(),r.startsAt(),r.durationMinutes(),r.meetingUrl(),r.status());emails.session(id);return Map.of("id",id);}
    public record AttendanceInput(@NotNull UUID sessionId,@NotNull UUID studentId,@NotNull @Pattern(regexp="PRESENT|ABSENT|LATE|EXCUSED")String status){}
    @GetMapping("/attendance") public List<?> attendance(Authentication a){AppUser u=identities.current(a);return db.queryForList("SELECT x.*,s.course_id,s.title,s.starts_at,s.batch_id FROM class_attendance x JOIN live_sessions s ON s.id=x.session_id").stream().filter(r->sessionVisible(r,u)&&(u.getRole()!=Role.STUDENT||u.getId().equals(uuid(r.get("student_id"))))).toList();}
    @PostMapping("/attendance") @Transactional public Map<String,Object> attendance(@Valid @RequestBody AttendanceInput r,Authentication a){AppUser u=identities.current(a);var session=one("SELECT * FROM live_sessions WHERE id=?",r.sessionId());teach(u,session.get("course_id").toString());if(!learnerInSession(session,r.studentId()))throw bad("Student must be enrolled and assigned to this session's batch.");if("CANCELLED".equals(session.get("status")))throw bad("Cannot mark a cancelled class.");db.update("DELETE FROM class_attendance WHERE session_id=? AND student_id=?",r.sessionId(),r.studentId());db.update("INSERT INTO class_attendance(session_id,student_id,status) VALUES(?,?,?)",r.sessionId(),r.studentId(),r.status());return Map.of("saved",true);}

    public record AssignmentInput(@NotBlank @Size(max=60)String courseId,@NotBlank @Size(max=150)String title,@NotBlank @Size(max=4000)String description,@NotNull OffsetDateTime dueAt){}
    @GetMapping("/assignments") public List<?> assignments(Authentication a){return visible("teaching_assignments",identities.current(a));}
    @PostMapping("/assignments") @Transactional public Map<String,Object> createAssignment(@Valid @RequestBody AssignmentInput r,Authentication a){return saveAssignment(UUID.randomUUID(),r,identities.current(a),false);}
    @PutMapping("/assignments/{id}") @Transactional public Map<String,Object> updateAssignment(@PathVariable UUID id,@Valid @RequestBody AssignmentInput r,Authentication a){return saveAssignment(id,r,identities.current(a),true);}
    private Map<String,Object> saveAssignment(UUID id,AssignmentInput r,AppUser u,boolean update){teach(u,r.courseId());if(update){var old=one("SELECT * FROM teaching_assignments WHERE id=?",id);teach(u,old.get("course_id").toString());if(!old.get("course_id").equals(r.courseId()))throw bad("Assignment course cannot be changed.");db.update("UPDATE teaching_assignments SET title=?,description=?,due_at=? WHERE id=?",r.title().strip(),r.description().strip(),r.dueAt(),id);}else db.update("INSERT INTO teaching_assignments(id,course_id,title,description,due_at) VALUES(?,?,?,?,?)",id,r.courseId(),r.title().strip(),r.description().strip(),r.dueAt());emails.assignment(id);return Map.of("id",id);}

    private static final Map<String,String> TYPES=Map.of("pdf","application/pdf","mp4","video/mp4","webm","video/webm","txt","text/plain","png","image/png","jpg","image/jpeg","jpeg","image/jpeg","zip","application/zip");
    @PostMapping(value="/files",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional
    public Map<String,Object> upload(@RequestParam String courseId,@RequestParam(required=false) UUID assignmentId,@RequestParam MultipartFile file,Authentication a)throws java.io.IOException{
        AppUser u=identities.current(a);require(canRead(u,courseId));
        if(u.getRole()==Role.STUDENT){require(assignmentId!=null);var assignment=one("SELECT * FROM teaching_assignments WHERE id=?",assignmentId);require(courseId.equals(assignment.get("course_id")));}else{teach(u,courseId);if(assignmentId!=null)throw bad("Teachers upload course resources without an assignment ID.");}
        if(file.isEmpty()||file.getSize()>20971520)throw bad("Choose a non-empty file up to 20 MB.");
        String name=Optional.ofNullable(file.getOriginalFilename()).orElse("file").replace('\\','/');name=name.substring(name.lastIndexOf('/')+1).replaceAll("[\\p{Cntrl}]","");if(name.isBlank()||name.length()>200)throw bad("Use a filename up to 200 characters.");
        String extension=name.contains(".")?name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT):"";String type=TYPES.get(extension);if(type==null)throw bad("Supported files: PDF, MP4, WebM, TXT, PNG, JPEG and ZIP.");
        byte[] bytes=file.getBytes();if(!signature(extension,bytes))throw bad("File content does not match its extension.");UUID id=UUID.randomUUID();
        db.update("INSERT INTO teaching_files(id,course_id,owner_id,assignment_id,name,content_type,size_bytes,content) VALUES(?,?,?,?,?,?,?,?)",id,courseId,u.getId(),assignmentId,name,type,bytes.length,bytes);
        return Map.of("id",id,"name",name,"size",bytes.length);
    }
    private boolean signature(String ext,byte[] b){return switch(ext){case "pdf"->b.length>=5&&new String(b,0,5,StandardCharsets.US_ASCII).equals("%PDF-");case "png"->b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71;case "jpg","jpeg"->b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;case "zip"->b.length>=4&&b[0]==80&&b[1]==75;case "mp4"->b.length>=12&&new String(b,4,4,StandardCharsets.US_ASCII).equals("ftyp");case "webm"->b.length>=4&&(b[0]&255)==26&&(b[1]&255)==69&&(b[2]&255)==223&&(b[3]&255)==163;default->true;};}
    public record ResourceInput(@NotBlank @Size(max=60)String courseId,@NotBlank @Size(max=150)String title,@NotNull UUID fileId){}
    @GetMapping("/resources") public List<?> resources(Authentication a){AppUser u=identities.current(a);return db.queryForList("SELECT r.*,f.name,f.size_bytes,f.content_type FROM teaching_resources r JOIN teaching_files f ON f.id=r.file_id").stream().filter(r->canRead(u,r.get("course_id").toString())).toList();}
    @PostMapping("/resources") @Transactional public Map<String,Object> resource(@Valid @RequestBody ResourceInput r,Authentication a){AppUser u=identities.current(a);teach(u,r.courseId());var f=one("SELECT owner_id,course_id,assignment_id FROM teaching_files WHERE id=?",r.fileId());require(u.getId().equals(uuid(f.get("owner_id")))&&r.courseId().equals(f.get("course_id"))&&f.get("assignment_id")==null);UUID id=UUID.randomUUID();db.update("INSERT INTO teaching_resources(id,course_id,title,file_id) VALUES(?,?,?,?)",id,r.courseId(),r.title().strip(),r.fileId());return Map.of("id",id);}
    public record SubmissionInput(@NotNull UUID assignmentId,@NotNull UUID fileId,@NotNull @Size(max=4000)String note){}
    @GetMapping("/submissions") public List<?> submissions(Authentication a){AppUser u=identities.current(a);return db.queryForList("SELECT s.*,a.course_id,a.title,a.due_at,f.name AS file_name,u.name AS student_name FROM assignment_submissions s JOIN teaching_assignments a ON a.id=s.assignment_id JOIN teaching_files f ON f.id=s.file_id JOIN app_users u ON u.id=s.student_id").stream().filter(r->canRead(u,r.get("course_id").toString())&&(u.getRole()!=Role.STUDENT||u.getId().equals(uuid(r.get("student_id"))))).toList();}
    @PostMapping("/submissions") @Transactional public Map<String,Object> submit(@Valid @RequestBody SubmissionInput r,Authentication a){AppUser u=identities.current(a);require(u.getRole()==Role.STUDENT);var assignment=one("SELECT * FROM teaching_assignments WHERE id=?",r.assignmentId());require(canRead(u,assignment.get("course_id").toString()));var f=one("SELECT owner_id,assignment_id FROM teaching_files WHERE id=?",r.fileId());require(u.getId().equals(uuid(f.get("owner_id")))&&r.assignmentId().equals(f.get("assignment_id")));var existing=db.queryForList("SELECT id,grade FROM assignment_submissions WHERE assignment_id=? AND student_id=?",r.assignmentId(),u.getId());UUID id;if(existing.isEmpty()){id=UUID.randomUUID();db.update("INSERT INTO assignment_submissions(id,assignment_id,student_id,file_id,note,submitted_at) VALUES(?,?,?,?,?,?)",id,r.assignmentId(),u.getId(),r.fileId(),r.note(),OffsetDateTime.now(clock));}else{if(existing.getFirst().get("grade")!=null)throw bad("Graded submissions cannot be replaced.");id=uuid(existing.getFirst().get("id"));db.update("UPDATE assignment_submissions SET file_id=?,note=?,submitted_at=? WHERE id=?",r.fileId(),r.note(),OffsetDateTime.now(clock),id);}return Map.of("id",id);}
    public record GradeInput(@Min(0) @Max(100) @NotNull Integer grade,@NotNull @Size(max=4000)String feedback){}
    @PutMapping("/submissions/{id}/grade") @Transactional public Map<String,Object> grade(@PathVariable UUID id,@Valid @RequestBody GradeInput r,Authentication a){AppUser u=identities.current(a);var row=one("SELECT a.course_id FROM assignment_submissions s JOIN teaching_assignments a ON a.id=s.assignment_id WHERE s.id=?",id);teach(u,row.get("course_id").toString());var now=OffsetDateTime.now(clock);db.update("UPDATE assignment_submissions SET grade=?,feedback=?,graded_by=?,graded_at=? WHERE id=?",r.grade(),r.feedback(),u.getId(),now,id);db.update("INSERT INTO submission_grade_history(id,submission_id,grader_id,grade,feedback,graded_at) VALUES(?,?,?,?,?,?)",UUID.randomUUID(),id,u.getId(),r.grade(),r.feedback(),now);return Map.of("saved",true);}
    @GetMapping("/submissions/{id}/history") public List<?> gradeHistory(@PathVariable UUID id,Authentication a){AppUser u=identities.current(a);var row=one("SELECT s.student_id,a.course_id FROM assignment_submissions s JOIN teaching_assignments a ON a.id=s.assignment_id WHERE s.id=?",id);require(canRead(u,row.get("course_id").toString())&&(u.getRole()!=Role.STUDENT||u.getId().equals(uuid(row.get("student_id")))));return db.queryForList("SELECT grade,feedback,grader_id,graded_at FROM submission_grade_history WHERE submission_id=? ORDER BY graded_at",id);}
    @GetMapping("/files/{id}") public ResponseEntity<byte[]> file(@PathVariable UUID id,Authentication a){AppUser u=identities.current(a);var meta=one("SELECT course_id,owner_id,assignment_id,name,content_type FROM teaching_files WHERE id=?",id);require(canRead(u,meta.get("course_id").toString()));boolean owner=u.getId().equals(uuid(meta.get("owner_id")));boolean resource=db.queryForObject("SELECT COUNT(*) FROM teaching_resources WHERE file_id=?",Integer.class,id)>0;boolean submitted=db.queryForObject("SELECT COUNT(*) FROM assignment_submissions WHERE file_id=?",Integer.class,id)>0;require(owner||resource||(u.getRole()!=Role.STUDENT&&submitted));byte[] content=db.queryForObject("SELECT content FROM teaching_files WHERE id=?",(rs,n)->rs.getBytes(1),id);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(meta.get("name").toString(),StandardCharsets.UTF_8).build().toString()).header(HttpHeaders.CACHE_CONTROL,"no-store").header("X-Content-Type-Options","nosniff").contentType(MediaType.parseMediaType(meta.get("content_type").toString())).body(content);}
}
